//! PolylineVisualizer matching CesiumJS `DataSources/PolylineVisualizer.js` (Apache-2.0).

use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

use crate::{
    BoundingSphere, BoundingSphereState, Cartesian3, Color, ColorGeometryInstanceAttribute,
    DeveloperError, Entity, EntityCollection, GeometryInstanceAttribute, JulianDate, ListenerId,
    PolylineGeometryUpdater, ShowGeometryInstanceAttribute,
};

/// Simulated Polyline primitive generated by `PolylineVisualizer`.
#[derive(Clone, Debug)]
pub struct PolylinePrimitive {
    pub entity_id: String,
    pub positions: Vec<Cartesian3>,
    pub width: f64,
    pub show: bool,
    pub clamp_to_ground: bool,
    pub attributes: HashMap<String, GeometryInstanceAttribute>,
    pub bounding_sphere: BoundingSphere,
}

impl PolylinePrimitive {
    pub fn new(entity_id: impl Into<String>) -> Self {
        Self {
            entity_id: entity_id.into(),
            positions: Vec::new(),
            width: 1.0,
            show: true,
            clamp_to_ground: false,
            attributes: HashMap::new(),
            bounding_sphere: BoundingSphere::default(),
        }
    }

    /// Gets geometry instance attributes for the specified entity.
    pub fn get_geometry_instance_attributes(&self, entity: &Entity) -> Option<&HashMap<String, GeometryInstanceAttribute>> {
        if self.entity_id == entity.id {
            Some(&self.attributes)
        } else {
            None
        }
    }
}

/// Simulated scene for `PolylineVisualizer`.
#[derive(Clone, Debug, Default)]
pub struct PolylineVisualizerScene {
    pub primitives: Rc<RefCell<Vec<PolylinePrimitive>>>,
    pub ground_primitives: Rc<RefCell<Vec<PolylinePrimitive>>>,
}

impl PolylineVisualizerScene {
    pub fn new() -> Self {
        Self {
            primitives: Rc::new(RefCell::new(Vec::new())),
            ground_primitives: Rc::new(RefCell::new(Vec::new())),
        }
    }

    pub fn primitives(&self) -> Rc<RefCell<Vec<PolylinePrimitive>>> {
        Rc::clone(&self.primitives)
    }

    pub fn ground_primitives(&self) -> Rc<RefCell<Vec<PolylinePrimitive>>> {
        Rc::clone(&self.ground_primitives)
    }
}

struct PolylineItemData {
    primitive_idx: usize,
    is_ground: bool,
}

/// A visualizer for polylines represented by Primitive instances.
pub struct PolylineVisualizer {
    scene: Rc<RefCell<PolylineVisualizerScene>>,
    entity_collection: Rc<RefCell<EntityCollection>>,
    updaters: HashMap<String, PolylineGeometryUpdater>,
    items: HashMap<String, PolylineItemData>,
    collection_subscription: Option<ListenerId>,
    destroyed: bool,
}

impl PolylineVisualizer {
    /// Creates a new `PolylineVisualizer`.
    pub fn new(
        scene: Option<Rc<RefCell<PolylineVisualizerScene>>>,
        entity_collection: Option<Rc<RefCell<EntityCollection>>>,
    ) -> Result<Self, DeveloperError> {
        let scene = scene.ok_or_else(|| DeveloperError::new("scene is required."))?;
        let entity_collection = entity_collection
            .ok_or_else(|| DeveloperError::new("entityCollection is required."))?;

        let mut visualizer = Self {
            scene,
            entity_collection: Rc::clone(&entity_collection),
            updaters: HashMap::new(),
            items: HashMap::new(),
            collection_subscription: None,
            destroyed: false,
        };

        visualizer.setup_collection_listener();
        Ok(visualizer)
    }

    fn setup_collection_listener(&mut self) {
        let sub = self.entity_collection.borrow_mut().collection_changed.add_listener(|_| {});
        self.collection_subscription = Some(sub);
    }

    /// Updates all primitives to match entity definitions at given time.
    pub fn update(&mut self, time: Option<JulianDate>) -> Result<bool, DeveloperError> {
        let time = time.ok_or_else(|| DeveloperError::new("time is required."))?;

        let entities: Vec<Entity> = self
            .entity_collection
            .borrow()
            .values()
            .into_iter()
            .cloned()
            .collect();

        let mut prims = self.scene.borrow().primitives.borrow().clone();
        let mut ground_prims = self.scene.borrow().ground_primitives.borrow().clone();

        // 1. Clean up any entities that have been removed from the collection
        let current_ids: std::collections::HashSet<String> =
            entities.iter().map(|e| e.id.clone()).collect();
        let removed_ids: Vec<String> = self
            .items
            .keys()
            .filter(|id| !current_ids.contains(*id))
            .cloned()
            .collect();

        for id in removed_ids {
            self.remove_entity_primitive(&id, &mut prims, &mut ground_prims);
        }

        // 2. Update or insert current entities
        for entity in entities {
            let polyline_graphics = match &entity.polyline {
                Some(p) => p,
                None => {
                    self.remove_entity_primitive(&entity.id, &mut prims, &mut ground_prims);
                    continue;
                }
            };

            let positions = polyline_graphics
                .positions
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)));

            let show = entity.is_showing()
                && entity.is_available(&time)
                && polyline_graphics
                    .show
                    .as_ref()
                    .and_then(|p| p.get_value(Some(&time)))
                    .unwrap_or(true);

            if positions.is_none() || !show {
                self.remove_entity_primitive(&entity.id, &mut prims, &mut ground_prims);
                continue;
            }

            let positions_vec = positions.unwrap();
            if positions_vec.is_empty() {
                self.remove_entity_primitive(&entity.id, &mut prims, &mut ground_prims);
                continue;
            }

            let width = polyline_graphics
                .width
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)))
                .unwrap_or(1.0);

            let clamp_to_ground = polyline_graphics
                .clamp_to_ground
                .as_ref()
                .and_then(|p| p.get_value(Some(&time)))
                .unwrap_or(false);

            let dvec_points: Vec<glam::DVec3> = positions_vec
                .iter()
                .map(|p| glam::DVec3::new(p.x, p.y, p.z))
                .collect();
            let bounding_sphere = BoundingSphere::from_points(&dvec_points).unwrap_or_default();

            let mut attributes = HashMap::new();
            let show_attr = ShowGeometryInstanceAttribute::new(show);
            if let Ok(attr) = GeometryInstanceAttribute::new(
                show_attr.component_datatype,
                show_attr.components_per_attribute,
                show_attr.normalize,
                vec![if show { 1.0 } else { 0.0 }],
            ) {
                attributes.insert("show".to_string(), attr);
            }

            let color_attr = ColorGeometryInstanceAttribute::from_color(Color::WHITE);
            if let Ok(attr) = GeometryInstanceAttribute::new(
                color_attr.component_datatype,
                color_attr.components_per_attribute,
                color_attr.normalize,
                color_attr.value.iter().map(|&v| v as f64).collect(),
            ) {
                attributes.insert("color".to_string(), attr);
            }

            // Remove from existing list if target list changed (ground vs normal)
            if let Some(existing) = self.items.get(&entity.id) {
                if existing.is_ground != clamp_to_ground {
                    self.remove_entity_primitive(&entity.id, &mut prims, &mut ground_prims);
                }
            }

            let target_list = if clamp_to_ground {
                &mut ground_prims
            } else {
                &mut prims
            };

            if let Some(pos) = target_list.iter().position(|p| p.entity_id == entity.id) {
                let prim = &mut target_list[pos];
                prim.show = show;
                prim.width = width;
                prim.positions = positions_vec;
                prim.clamp_to_ground = clamp_to_ground;
                prim.attributes = attributes;
                prim.bounding_sphere = bounding_sphere;
                self.items.insert(
                    entity.id.clone(),
                    PolylineItemData {
                        primitive_idx: pos,
                        is_ground: clamp_to_ground,
                    },
                );
            } else {
                let mut prim = PolylinePrimitive::new(&entity.id);
                prim.show = show;
                prim.width = width;
                prim.positions = positions_vec;
                prim.clamp_to_ground = clamp_to_ground;
                prim.attributes = attributes;
                prim.bounding_sphere = bounding_sphere;
                target_list.push(prim);
                self.items.insert(
                    entity.id.clone(),
                    PolylineItemData {
                        primitive_idx: target_list.len() - 1,
                        is_ground: clamp_to_ground,
                    },
                );
            }
        }

        *self.scene.borrow().primitives.borrow_mut() = prims;
        *self.scene.borrow().ground_primitives.borrow_mut() = ground_prims;

        Ok(true)
    }

    fn remove_entity_primitive(
        &mut self,
        entity_id: &str,
        prims: &mut Vec<PolylinePrimitive>,
        ground_prims: &mut Vec<PolylinePrimitive>,
    ) {
        if let Some(item_data) = self.items.remove(entity_id) {
            if item_data.is_ground {
                ground_prims.retain(|p| p.entity_id != entity_id);
            } else {
                prims.retain(|p| p.entity_id != entity_id);
            }
        }
    }

    /// Computes bounding sphere enclosing the polyline visualization.
    pub fn get_bounding_sphere(
        &self,
        entity: Option<&Entity>,
        result: Option<&mut BoundingSphere>,
    ) -> Result<BoundingSphereState, DeveloperError> {
        let entity = entity.ok_or_else(|| DeveloperError::new("entity is required."))?;
        let result = result.ok_or_else(|| DeveloperError::new("result is required."))?;

        if let Some(item_data) = self.items.get(&entity.id) {
            let scene = self.scene.borrow();
            let target_list = if item_data.is_ground {
                scene.ground_primitives.borrow()
            } else {
                scene.primitives.borrow()
            };

            if item_data.primitive_idx < target_list.len() {
                let prim = &target_list[item_data.primitive_idx];
                *result = prim.bounding_sphere;
                return Ok(BoundingSphereState::Done);
            }
        }

        Ok(BoundingSphereState::Failed)
    }

    /// Returns true if destroyed.
    pub fn is_destroyed(&self) -> bool {
        self.destroyed
    }

    /// Destroys this visualizer.
    pub fn destroy(&mut self) {
        if let Some(sub) = self.collection_subscription.take() {
            self.entity_collection.borrow_mut().collection_changed.remove_listener(sub);
        }
        self.updaters.clear();
        self.items.clear();
        self.scene.borrow().primitives.borrow_mut().clear();
        self.scene.borrow().ground_primitives.borrow_mut().clear();
        self.destroyed = true;
    }
}

impl Drop for PolylineVisualizer {
    fn drop(&mut self) {
        if !self.destroyed {
            self.destroy();
        }
    }
}

impl std::fmt::Debug for PolylineVisualizer {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.debug_struct("PolylineVisualizer")
            .field("destroyed", &self.destroyed)
            .finish()
    }
}

impl crate::visualizer::Visualizer for PolylineVisualizer {
    fn update(&mut self, time: &JulianDate) -> bool {
        self.update(Some(*time)).unwrap_or(false)
    }

    fn get_bounding_sphere(
        &self,
        entity: &Entity,
        result: &mut BoundingSphere,
    ) -> BoundingSphereState {
        self.get_bounding_sphere(Some(entity), Some(result))
            .unwrap_or(BoundingSphereState::Failed)
    }

    fn is_destroyed(&self) -> bool {
        self.is_destroyed()
    }

    fn destroy(&mut self) {
        self.destroy();
    }
}
